// Rust guideline compliant 2026-02-21

use gpui_mesh::{DataSet,Field};
use gpui_scene3d::{Actor,Camera,ClipPlane,Projection,Scene,TransferFunction,render};
use gpui_profiler::AllocProbe;
use std::{hint::black_box,time::Instant};

fn cpu_ns() -> u128 {
    let mut stamp=libc::timespec {tv_sec:0,tv_nsec:0};
    // SAFETY: stamp is valid writable storage for this synchronous clock call,
    // which retains no pointer. The return status and timestamp are checked.
    let result=unsafe {libc::clock_gettime(libc::CLOCK_PROCESS_CPUTIME_ID,&mut stamp)};
    assert_eq!(result,0);
    assert!(stamp.tv_sec>=0 && (0..1_000_000_000).contains(&stamp.tv_nsec));
    stamp.tv_sec as u128*1_000_000_000+stamp.tv_nsec as u128
}

fn dataset(n: usize) -> DataSet {
    if n==0 {
        DataSet::surface("plane",vec![[-1.0,-1.0,0.0],[1.0,-1.0,0.0],[1.0,1.0,0.0],[-1.0,1.0,0.0]],&[[0,1,2],[0,2,3]])
            .with_field(Field::scalar("p",vec![0.0,1.0,0.75,0.25]))
    } else {
        let d=DataSet::structured_grid("grid",[n;3],[-1.0;3],[2.0/(n-1) as f64;3]).unwrap();
        let p=d.positions.iter().map(|p|(p[0]+1.0)*0.5).collect::<Vec<_>>();
        d.with_field(Field::scalar("p",p))
    }
}

fn run(n: usize, size: u32, kind: &str, clipped: bool) {
    let data=dataset(n);
    let mut actor=if kind=="flat" {Actor::new(data).color([0.2,0.7,0.4,1.0])} else {
        Actor::new(data).coloured_by("p",TransferFunction::viridis([0.0,1.0]))
    };
    if kind=="alpha" {actor.opacity=0.5;}
    if clipped {actor=actor.clip(ClipPlane {origin:[0.0;3],normal:[1.0,0.5,0.0]});}
    let scene=Scene::new().with_actor(actor);
    let camera=if n==0 {Camera {azimuth:0.0,elevation:0.0,distance:3.0,projection:Projection::Perspective {fov_y:std::f32::consts::FRAC_PI_2},..Camera::default()}} else {Camera::fitted(scene.bounds().unwrap())};
    let warm=render(&scene,&camera,size,size).unwrap();
    assert_eq!(warm.rgba.len(),size as usize*size as usize*4);
    let background=scene.background.map(|v|(v.clamp(0.0,1.0)*255.0) as u8);
    assert!(warm.rgba.chunks_exact(4).any(|p|p!=background));
    let (mut times,mut cpus,mut calls,mut bytes)=(Vec::new(),Vec::new(),Vec::new(),Vec::new());
    for _ in 0..5 {
        let mut probe=AllocProbe::new(); let before=cpu_ns(); let start=Instant::now();
        let out=black_box(render(&scene,&camera,size,size).unwrap());
        let elapsed=start.elapsed().as_nanos(); let cpu=cpu_ns()-before;
        let allocation=probe.sample("surface");
        times.push(elapsed);cpus.push(cpu);calls.push(allocation.count);bytes.push(allocation.bytes);
        assert_eq!(out.rgba,warm.rgba);drop(out);
    }
    assert_eq!(scene.preparation_stats().geometry_builds,1);
    println!(r#"{{"n":{n},"size":{size},"kind":"{kind}","clipped":{clipped},"times_ns":{times:?},"cpu_times_ns":{cpus:?},"allocation_calls":{calls:?},"allocated_bytes":{bytes:?},"allocator_instrumentation":{}}}"#,cfg!(feature="allocations"));
}

fn main() {
    for n in [8,24,48] {for kind in ["flat","gradient","alpha"] {run(n,128,kind,false);}}
    for kind in ["flat","gradient","alpha"] {run(24,512,kind,false);run(24,128,kind,true);}
    for size in [128,512] {for kind in ["flat","gradient","alpha"] {run(0,size,kind,false);}}
}
